static class EngineManagementChecks
{
    [DllImport("user32.dll")]static extern bool SetProcessDPIAware();
    static int checks;static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
    sealed class TestDownloadsForm : EngineDownloadsForm{public bool Approve;public int Requests;public TestDownloadsForm(EngineDownloadManager manager):base(manager){}protected override bool ConfirmCancelDownload(EnginePackage package){Requests++;return Approve;}}
    static T Field<T>(object value,string name){for(var type=value.GetType();type!=null;type=type.BaseType){var field=type.GetField(name,BindingFlags.Instance|BindingFlags.NonPublic);if(field!=null)return (T)field.GetValue(value);}throw new Exception("missing field "+name);}
    static object Call(object value,string name,params object[] args){for(var type=value.GetType();type!=null;type=type.BaseType){var method=type.GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic);if(method!=null)return method.Invoke(value,args);}throw new Exception("missing method "+name);}
    static void Until(Func<bool> ready){var clock=System.Diagnostics.Stopwatch.StartNew();while(!ready()){Application.DoEvents();Thread.Sleep(5);if(clock.Elapsed.TotalSeconds>20)throw new Exception("management timeout");}}
    static void Wait(Task task){Until(()=>task.IsCompleted);task.GetAwaiter().GetResult();}
    static EnginePackage Package(string id){return new EnginePackage{Id=id,Name="测试资源 "+id,Folder="models/"+id,Bytes=100,Archive="file",FileName="model.bin",Url="https://example.invalid/fixture",Sha256=new string('0',64)};}
    static string Fragment(EngineStore store,EnginePackage p){return Path.Combine(store.Root,"downloads",p.Id+".part");}
    static void Shot(Form form,string path){Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,form.Size));image.Save(path);}}
    static bool HasText(Control parent,string text){return parent.Text.Contains(text)||parent.Controls.Cast<Control>().Any(child=>HasText(child,text));}
    [STAThread]static int Main(string[] args)
    {
        try
        {
            if(args.Length>1&&args[1]=="--dpi-aware")SetProcessDPIAware();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var store=new EngineStore(Path.Combine(root,"外置资源"));Directory.CreateDirectory(Path.Combine(store.Root,"downloads"));
            var a=Package("a");var b=Package("b");var c=Package("queued");int resumed=-1;
            using(var manager=new EngineDownloadManager(store,1,(p,t,r)=>{string partial=Fragment(store,p);using(var output=new FileStream(partial,FileMode.OpenOrCreate,FileAccess.Write,FileShare.Read)){if(p.Id==a.Id)Interlocked.Exchange(ref resumed,(int)output.Length);output.Position=output.Length;output.Write(new byte[30],0,30);output.Flush();r(new EngineProgress{Written=output.Length,Total=100,Message="正在下载"});t.WaitHandle.WaitOne();t.ThrowIfCancellationRequested();}}))
            {
                manager.Enqueue(new[]{a,b});Until(()=>store.PartialBytes(a)==30);manager.Pause(a.Id);Until(()=>manager.Snapshots.Single(s=>s.Package.Id==a.Id).State==EngineTaskState.Paused);Check(store.PartialBytes(a)==30,"pause retains a complete closed download fragment");Until(()=>store.PartialBytes(b)==30);Check(manager.IsActive(b.Id),"pausing one resource lets the next queued resource run");
                File.WriteAllBytes(Fragment(store,c),new byte[12]);manager.Enqueue(new[]{c});Until(()=>manager.Snapshots.Single(s=>s.Package.Id==c.Id).State==EngineTaskState.Queued);manager.Cancel(c);Until(()=>manager.Snapshots.Single(s=>s.Package.Id==c.Id).State==EngineTaskState.Cancelled);Check(!File.Exists(Fragment(store,c)),"cancelling a queued resource removes its preexisting fragment");
                manager.Cancel(a);Until(()=>manager.Snapshots.Single(s=>s.Package.Id==a.Id).State==EngineTaskState.Cancelled);Check(!File.Exists(Fragment(store,a))&&manager.Snapshots.Single(s=>s.Package.Id==a.Id).Written==0,"cancelling a paused download deletes data and resets progress");Check(store.PartialBytes(b)==30&&manager.IsActive(b.Id),"cancel cleanup does not touch a different resource");
                Wait(manager.StopAsync());Check(store.PartialBytes(b)==30&&manager.Snapshots.Single(s=>s.Package.Id==b.Id).State==EngineTaskState.Paused,"closing pauses remaining work and preserves progress");
            }
            File.WriteAllBytes(Fragment(store,a),new byte[20]);using(var manager=new EngineDownloadManager(store,1,(p,t,r)=>{using(var output=new FileStream(Fragment(store,p),FileMode.OpenOrCreate,FileAccess.Write,FileShare.Read)){resumed=(int)output.Length;output.Position=output.Length;output.WriteByte(1);output.Flush();r(new EngineProgress{Written=output.Length,Total=100,Message="正在下载"});t.WaitHandle.WaitOne();t.ThrowIfCancellationRequested();}}))
            {
                manager.Enqueue(new[]{a});Until(()=>resumed==20&&store.PartialBytes(a)==21);Check(resumed==20,"a fresh manager resumes an existing download rather than overwriting it");manager.Cancel(a);Until(()=>!manager.HasActive);Check(!File.Exists(Fragment(store,a)),"active cancellation waits for the writer to close before deleting its fragment");
            }
            using(var manager=new EngineDownloadManager(store)){File.WriteAllBytes(Fragment(store,a),new byte[8]);File.SetAttributes(Fragment(store,a),FileAttributes.ReadOnly);manager.Cancel(a);Until(()=>!manager.HasActive);Check(manager.Snapshots.Single().State==EngineTaskState.Failed&&File.Exists(Fragment(store,a)),"a cleanup failure never falsely reports that download data was deleted");File.SetAttributes(Fragment(store,a),FileAttributes.Normal);manager.Cancel(a);Until(()=>!manager.HasActive);Check(!File.Exists(Fragment(store,a))&&manager.Snapshots.Single().State==EngineTaskState.Cancelled,"failed cleanup can be retried once file permissions are corrected");}
            string archive=Path.Combine(root,"model.bin");File.WriteAllText(archive,"managed fixture");var installed=Package("installed");installed.Bytes=new FileInfo(archive).Length;installed.Sha256=EngineStore.Hash(archive,CancellationToken.None);store.InstallArchive(installed,archive,CancellationToken.None,s=>{});Check(store.Installed(installed),"real file installation creates a manageable receipt");string original=Path.Combine(store.Root,"keep-original.txt");File.WriteAllText(original,"keep");
            using(store.Use(installed.Id)){bool blocked=false;try{store.Uninstall(installed);}catch(IOException){blocked=true;}Check(blocked&&store.Installed(installed),"an active processing lease prevents any engine file deletion");}
            string installedFile=Path.Combine(store.PackageRoot(installed),"model.bin");using(var locked=new FileStream(installedFile,FileMode.Open,FileAccess.Read,FileShare.Read)){bool blocked=false;try{store.Uninstall(installed);}catch(IOException){blocked=true;}Check(blocked&&store.Installed(installed),"a file locked by another process fails preflight without a partial uninstall");}
            File.WriteAllBytes(Fragment(store,installed),new byte[9]);using(var manager=new EngineDownloadManager(store)){manager.Uninstall(installed);Until(()=>!manager.HasActive);Check(!Directory.Exists(store.PackageRoot(installed))&&!File.Exists(Fragment(store,installed)),"uninstall removes only the selected package and its obsolete fragment");Check(File.ReadAllText(original)=="keep"&&File.Exists(Fragment(store,b)),"uninstall preserves sibling resources and unrelated files");}
            var unknown=Package("unknown");Directory.CreateDirectory(store.PackageRoot(unknown));File.WriteAllText(Path.Combine(store.PackageRoot(unknown),"keep.txt"),"keep");bool rejected=false;try{store.Uninstall(unknown);}catch(IOException){rejected=true;}Check(rejected&&File.Exists(Path.Combine(store.PackageRoot(unknown),"keep.txt")),"an unregistered directory is never recursively deleted");rejected=false;try{store.Uninstall(new EnginePackage{Id="invalid",Folder="models/.."});}catch(IOException){rejected=true;}Check(rejected&&File.Exists(original),"uninstall rejects parent-directory targets");
            string zip=Path.Combine(root,"voice.zip");var manifest=new LocalVoiceManifest{Name="我的测试音色",Adapter="kokoro",Model="model.onnx",VoicesFile="voices.bin",Tokens="tokens.txt",Lexicons="lexicon.txt",Voices=new[]{new SpeechVoice{Id=0,Name="测试音色",Language="zh",Gender="女"}}};using(var package=ZipFile.Open(zip,ZipArchiveMode.Create)){foreach(string name in new[]{"model.onnx","voices.bin","tokens.txt","lexicon.txt"})using(var writer=new StreamWriter(package.CreateEntry(name).Open()))writer.Write("fixture");using(var writer=new StreamWriter(package.CreateEntry("voice-pack.json").Open()))writer.Write(new JavaScriptSerializer().Serialize(manifest));}
            var custom=store.ImportVoicePack(zip,CancellationToken.None);var catalog=EngineResources.All(store);Check(catalog.Length==8&&catalog.Count(r=>r.Downloadable)==7,"inventory contains all seven official resources plus imported voice packs");Check(catalog.Single(r=>r.Package.Id==VideoCatalog.Runtime.Id).Usage.Contains("GIF")&&catalog.Single(r=>r.Package.Id==SpeechCatalog.Whisper.Id).Usage.Contains("共用"),"help describes each feature and common-engine dependencies");
            File.WriteAllBytes(Fragment(store,SpeechCatalog.Tiny),new byte[1024]);
            using(var manager=new EngineDownloadManager(store))using(var form=new EngineDownloadsForm(manager))
            {
                form.Show();Application.DoEvents();Check(!form.Modal,"inventory remains modeless");var rows=Field<IDictionary>(form,"rows");Check(rows.Count==8,"the window lists resources even when no task was started");var tiny=(Control)rows[SpeechCatalog.Tiny.Id];Check(Field<ModernButton>(tiny,"primary").Text=="继续下载"&&Field<ModernButton>(tiny,"secondary").Visible,"paused fragments are rediscovered after reopening the manager");var video=(Control)rows[VideoCatalog.Runtime.Id];Check(Field<SmoothProgress>(video,"progress").Value==0&&Field<ModernButton>(video,"primary").Text=="下载","never-downloaded resources have an empty bar and a download action");var imported=(Control)rows[custom.Id];Check(Field<Label>(imported,"status").Text=="已下载"&&Field<ModernButton>(imported,"uninstall").Enabled,"installed imported resources show downloaded state and uninstall");Check(Field<ToolTip>(form,"tips").GetToolTip(Field<Control>(video,"info")).Contains("视频转 GIF"),"the info icon has a readable feature tooltip");
                Check(form.Text=="功能扩展包下载"&&HasText(form,"功能扩展包下载")&&!HasText(form,"按需下载，安装后离线使用。最多同时下载"),"the new title is present and the redundant header note is removed");
                int idleVisibilityChanges=0;Field<ModernButton>(video,"primary").VisibleChanged+=(s,e)=>idleVisibilityChanges++;Field<ModernButton>(imported,"uninstall").VisibleChanged+=(s,e)=>idleVisibilityChanges++;for(int refresh=0;refresh<12;refresh++){Call(form,"RefreshTasks");Application.DoEvents();}Check(idleVisibilityChanges==0,"idle download and uninstall buttons never hide and reappear during polling");
                Check(!Field<Label>(video,"detail").Text.Contains("已安装")&&Field<Label>((Control)rows[SpeechCatalog.Kokoro11.Id],"detail").Text.Contains("任选一套"),"missing resources never claim installed and voice alternatives are explained inline");
                using(store.Use(custom.Id)){Call(form,"RefreshTasks");Check(!Field<ModernButton>(imported,"uninstall").Enabled,"the uninstall button is disabled while its resource is in use");}
                Call(form,"RefreshTasks");Check(Field<ModernButton>(imported,"uninstall").Enabled,"uninstall becomes available when processing releases the resource");Shot(form,Path.Combine(root,"engine-inventory.png"));
                form.Size=form.MinimumSize;Application.DoEvents();Call(form,"FitRows");Check(rows.Values.Cast<Control>().All(r=>r.Right<=r.Parent.ClientSize.Width),"resource cards fit the smallest manager window without horizontal clipping");
                var list=Field<ScrollableControl>(form,"list");Check(!list.HorizontalScroll.Visible,"shrinking the manager never leaves a stale horizontal scrollbar");
                var heading=list.Controls.Cast<Control>().First(candidate=>candidate.AccessibleRole==AccessibleRole.Grouping);Check(Field<Label>(heading,"Caption").Font.SizeInPoints>Field<Label>(video,"title").Font.SizeInPoints,"feature headings are visually stronger than engine names");
                Check(new[]{SpeechCatalog.Whisper,SpeechCatalog.Tiny,SpeechCatalog.Base}.All(p=>((Control)rows[p.Id]).Bottom<=list.ClientSize.Height),"the first complete three-resource group fits the minimum window");Check(rows.Values.Cast<Control>().All(r=>r.Height<=form.MinimumSize.Height*.16),"resource rows stay compact rather than filling oversized cards");Shot(form,Path.Combine(root,"engine-inventory-minimum.png"));list.AutoScrollPosition=new Point(0,list.AutoScrollMinSize.Height);list.PerformLayout();Check(imported.Bottom<=list.ClientSize.Height&&imported.Top>=0&&!list.HorizontalScroll.Visible,"vertical scrolling reaches the final imported resource without horizontal overflow");Shot(form,Path.Combine(root,"engine-inventory-end.png"));Console.WriteLine("MANAGER_LAYOUT_SCALE="+Field<float>(form,"scale"));form.Close();
            }
            var importedPackage=store.ImportedPackages().Single(p=>p.Id==custom.Id);store.Uninstall(importedPackage);Check(!store.ImportedPackages().Any(p=>p.Id==custom.Id),"imported voice packages can be safely unregistered and removed");
            Action<EngineProgress> reportProgress=null;
            using(var manager=new EngineDownloadManager(store,1,(p,t,r)=>{using(var output=new FileStream(Fragment(store,p),FileMode.OpenOrCreate,FileAccess.Write,FileShare.Read)){output.SetLength(p.Bytes/2);output.Flush();reportProgress=r;r(new EngineProgress{Written=p.Bytes/2,Total=p.Bytes,Message="正在下载 · 50%"});t.WaitHandle.WaitOne();t.ThrowIfCancellationRequested();}}))using(var form=new TestDownloadsForm(manager))
            {
                manager.Enqueue(new[]{SpeechCatalog.Tiny});Until(()=>manager.Snapshots.Single().Written>0);form.Show();Application.DoEvents();var rows=Field<IDictionary>(form,"rows");var tiny=(Control)rows[SpeechCatalog.Tiny.Id];Call(form,"RefreshTasks");Check(Field<ModernButton>(tiny,"primary").Text=="暂停"&&Field<ModernButton>(tiny,"secondary").Text=="取消下载","active download exposes separate pause and cancel actions");
                int activeVisibilityChanges=0;Field<ModernButton>(tiny,"primary").VisibleChanged+=(s,e)=>activeVisibilityChanges++;Field<ModernButton>(tiny,"secondary").VisibleChanged+=(s,e)=>activeVisibilityChanges++;for(int percent=51;percent<=60;percent++){reportProgress(new EngineProgress{Written=SpeechCatalog.Tiny.Bytes*percent/100,Total=SpeechCatalog.Tiny.Bytes,Message="正在下载 · "+percent+"%"});Call(form,"RefreshTasks");Application.DoEvents();}Check(activeVisibilityChanges==0&&Field<SmoothProgress>(tiny,"progress").Value==manager.Snapshots.Single().Percent&&Field<SmoothProgress>(tiny,"progress").Value>50,"changing download progress updates the bar without toggling pause or cancel visibility");
                Shot(form,Path.Combine(root,"engine-inventory-downloading.png"));Field<ModernButton>(tiny,"secondary").PerformClick();Check(form.Requests==1&&manager.HasActive&&store.PartialBytes(SpeechCatalog.Tiny)>0,"declining cancellation keeps the active task and its download progress");Field<ModernButton>(tiny,"primary").PerformClick();Until(()=>!manager.HasActive);Call(form,"RefreshTasks");Check(store.PartialBytes(SpeechCatalog.Tiny)>0&&Field<ModernButton>(tiny,"primary").Text=="继续下载","the pause button retains data and changes into resume");Field<ModernButton>(tiny,"secondary").PerformClick();Check(form.Requests==2&&store.PartialBytes(SpeechCatalog.Tiny)>0,"declining cancellation also preserves a paused fragment");form.Approve=true;Field<ModernButton>(tiny,"secondary").PerformClick();Until(()=>!manager.HasActive);Call(form,"RefreshTasks");Check(form.Requests==3&&store.PartialBytes(SpeechCatalog.Tiny)==0&&Field<SmoothProgress>(tiny,"progress").Value==0,"only confirmed cancellation deletes data and clears the progress bar");Check(!HasText(form,"暂停保留进度"),"the redundant footer note is removed from the download window");form.Close();
            }
            using(var dialog=new CancelDownloadDialog("轻量中英文识别模型"))using(var timer=new System.Windows.Forms.Timer{Interval=80}){Check(dialog.AcceptButton==dialog.CancelButton&&HasText(dialog,"当前进度会丢失"),"cancellation warning explains lost progress and defaults to keeping the download");timer.Tick+=(s,e)=>{timer.Stop();Shot(dialog,Path.Combine(root,"cancel-download-warning.png"));dialog.Close();};timer.Start();Check(dialog.ShowDialog()==DialogResult.Cancel,"closing the cancellation warning preserves the download");}
            Console.WriteLine("ALL "+checks+" ENGINE MANAGEMENT CHECKS PASSED");return 0;
        }catch(Exception error){Console.Error.WriteLine(error);return 1;}
    }
}
